# owner: platform
"""Find the stretches of opening hours nobody covers."""

from typing import Iterable

from hourglass.merging import merge_spans
from hourglass.models import Span
from hourglass.parsing import format_span


def _check_inside(spans, opening):
    for span in spans:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(
                f"{format_span(span)} is outside opening hours"
            )


def _labels(starts, ends):
    return [
        f"gap {format_span(Span(a, b))} ({b - a} min)"
        for a, b in zip(starts, ends)
        if a < b
    ]

# ---
def find_gaps(worked: Iterable[Span], opening: Span):
    spans = list(worked)
    _check_inside(spans, opening)
    edges = [opening.start]
    for s in merge_spans(spans):
        edges += [s.start, s.end]
    edges.append(opening.end)
    return _labels(edges[::2], edges[1::2])

